import{b as e,O as t,g as l,j as a}from"./chunks/framework.DcaUmd3X.js";const d=JSON.parse('{"title":"笑场","description":"","frontmatter":{},"headers":[],"relativePath":"reading/digital/laughing-stage/index.md","filePath":"读书感悟/电子书架/30.笑场.md","lastUpdated":1781614933000}'),c={name:"reading/digital/laughing-stage/index.md"};function p(u,o,b,q,k,r){return t(),l("div",null,[...o[0]||(o[0]=[a('<h1 id="笑场" tabindex="-1">笑场 <a class="header-anchor" href="#笑场" aria-label="Permalink to &quot;笑场&quot;">​</a></h1><p><code>李诞</code> <code>散文杂著</code></p><h2 id="书摘" tabindex="-1">书摘 <a class="header-anchor" href="#书摘" aria-label="Permalink to &quot;书摘&quot;">​</a></h2><blockquote><p>📌 未曾开言我先笑场，笑场完了听我诉一诉衷肠。</p></blockquote><blockquote><p>📌 “众生平等，不是说众生都有一样的价值，而是说众生都一样没有价值。”</p></blockquote><blockquote><p>📌 而眼前只有这一条路，可他心里并不知道这条路是不是对的路，也不知道尽头在哪里。这是很强的导演意图，象征着我们每个人的人生也差不多就是这样。</p></blockquote><blockquote><p>📌 人就是总给自己太多退路，世界才变成这样。人</p></blockquote><blockquote><p>📌 宇宙是震动的幻象，所谓命运是没有规律的碰撞”</p></blockquote><blockquote><p>📌 命运是所有人、所有事一起无意识地努力造成的，由于其庞大复杂，掌握、追随或者改变命运都是不可能的，你只能加入命运，做出一些微小的影响</p></blockquote><blockquote><p>📌 小时候我在床上乱爬，差点儿掉地上摔死，然后……”“那能一样吗？”说完走了。</p></blockquote><blockquote><p>📌 愿您也睡个好觉，不用再行神迹，躺着多过站着，我的荒谬之神。</p></blockquote><blockquote><p>📌 想到，有时所谓“事后诸葛亮”，可能是他事前说的时候根本没人听。 四</p></blockquote><blockquote><p>📌 给人适应的时间，是上天的仁慈。 然后每次适应一点儿，就又衰老一点儿。上天仁慈有限。</p></blockquote><blockquote><p>📌 不需要热泪热血，不需要在温水中一跃而起，要的是一点儿一点儿的消耗。</p></blockquote><blockquote><p>📌 一个朋友说自己在看牡丹，很多很多牡丹，很美。 我想不出那样的场面，在画里见得次数太多，已经疑心牡丹是否真的存在。</p></blockquote><blockquote><p>📌 车里看路人，一个大哥，走着走着绊了一跤，第一反应不是看是什么绊了自己，是看四周有没有人看他。 他以为没人看他，继续轻松前进。 为使轻松成真，我也不再看他。</p></blockquote><blockquote><p>📌 想把事儿做好，就得大材小用，可我们都做不到，所有人都在硬撑，都想往上够一点儿，也只能够着一点儿。</p></blockquote><blockquote><p>📌 抬头一片茫茫，想到，我们看星星，看到的不是星星，是自己视力的极限。</p></blockquote><blockquote><p>📌 看了四遍，也没记住名字。喜欢人生中这样的细节。人生中到处都是这样的细节。</p></blockquote><blockquote><p>📌 再互相憎恨的人 也得睡在同一个夜里</p></blockquote><blockquote><p>📌 人能做出最懦弱的事 就是只对自己强硬</p></blockquote><blockquote><p>📌 整夜失眠 天花板后面是星空 星空后面是我想象力受辱的地方</p></blockquote><h2 id="书评" tabindex="-1">书评 <a class="header-anchor" href="#书评" aria-label="Permalink to &quot;书评&quot;">​</a></h2><blockquote><p>💭 当别人对你好的时候就会觉得不应该对你这么好，会觉得不自在，反而会觉得对你越好你越对他有亏欠，想要弥补，当他有亏欠你的时候，你的良知就会告诉你，我们互不相欠了</p><p>📌 想到这里，我又说了句“没关系”。心怀感激。</p></blockquote><blockquote><p>💭 说多了会尴尬</p><p>📌 那过生日的人在听第一遍的时候，应该是快乐的。</p></blockquote><blockquote><p>💭 世事无常</p><p>📌 其实无所谓，轻松一点儿，灾难与你正当、快乐的生活并没什么不同，都是无常。</p></blockquote><h2 id="读后感" tabindex="-1">读后感 <a class="header-anchor" href="#读后感" aria-label="Permalink to &quot;读后感&quot;">​</a></h2><blockquote><p>未曾开言我先笑场，笑场完了听我诉一诉衷肠。</p></blockquote>',28)])])}const n=e(c,[["render",p]]);export{d as __pageData,n as default};
